// التحقق من هوية المدرس عن طريق Supabase (والنتيجة بتتحفظ 5 دقايق عشان السرعة)
const SUPABASE_URL = 'https://qdpnupgqvjxlrmwwgmij.supabase.co';
const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFkcG51cGdxdmp4bHJtd3dnbWlqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Njk5NjczMjUsImV4cCI6MjA4NTU0MzMyNX0.gaWPEgrhIQJzZLVoo7x1hnS-63ZJPZN96Xb3WpqApik';
const req = $input.first().json;
const headers = req.headers || {};
const token = String(headers.authorization || headers.Authorization || '').replace(/^Bearer\s+/i, '').trim();
if (!token || token.split('.').length < 3) return [{ json: { ok: false, code: 'UNAUTHORIZED' } }];
const cache = $getWorkflowStaticData('global');
cache.__auth = cache.__auth || {};
const key = token.slice(-32);
let uid = cache.__auth[key] && cache.__auth[key].until > Date.now() ? cache.__auth[key].uid : null;
if (!uid) {
  let user = null;
  try {
    user = await this.helpers.httpRequest({ method: 'GET', url: SUPABASE_URL + '/auth/v1/user', headers: { apikey: SUPABASE_ANON_KEY, Authorization: 'Bearer ' + token }, json: true, timeout: 8000 });
  } catch (e) { return [{ json: { ok: false, code: 'UNAUTHORIZED' } }]; }
  if (!user || !user.id) return [{ json: { ok: false, code: 'UNAUTHORIZED' } }];
  uid = user.id;
  const keys = Object.keys(cache.__auth);
  if (keys.length > 500) keys.slice(0, 250).forEach((k) => delete cache.__auth[k]);
  cache.__auth[key] = { uid, until: Date.now() + 5 * 60 * 1000 };
}
const body = req.body || {};
// طلبات الاشتراكات من لوحة المتابعة
const ALLOWED = ['billing_overview', 'billing_teachers', 'billing_payments', 'billing_activate', 'billing_adjust', 'billing_undo'];
const section = ALLOWED.includes(body.section) ? body.section : 'billing_overview';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const str = (v, n) => String(v == null ? '' : v).slice(0, n);
const q = { section };
if (UUID_RE.test(str(body.teacher_id, 40))) q.teacher_id = str(body.teacher_id, 40);
if (UUID_RE.test(str(body.id, 40))) q.id = str(body.id, 40);
if (['starter', 'pro'].includes(body.plan)) q.plan = body.plan;
if (['monthly', 'semiannual', 'annual', 'custom'].includes(body.period)) q.period = body.period;
if (['payment', 'gift'].includes(body.kind)) q.kind = body.kind;
if (['change_plan', 'set_end', 'stop', 'trial_until'].includes(body.action)) q.action = body.action;
if (body.months !== undefined && body.months !== '') q.months = String(Math.max(0, Math.min(36, parseInt(body.months, 10) || 0)));
if (body.extra_days !== undefined && body.extra_days !== '') q.extra_days = String(Math.max(0, Math.min(365, parseInt(body.extra_days, 10) || 0)));
if (body.amount !== undefined && body.amount !== '') { const a = Number(String(body.amount).replace(/[٠-٩]/g, (c) => c.charCodeAt(0) - 1632).replace(/[^\d.]/g, '')); if (isFinite(a)) q.amount = String(a); }
for (const k of ['starts_at', 'paid_at', 'date']) if (DATE_RE.test(str(body[k], 10))) q[k] = str(body[k], 10);
if (body.method) q.method = str(body.method, 40);
if (body.note) q.note = str(body.note, 500);
if (body.reason) q.reason = str(body.reason, 300);
const needTeacher = ['billing_activate', 'billing_adjust'].includes(section);
if ((needTeacher && !q.teacher_id) || (section === 'billing_undo' && !q.id)) return [{ json: { ok: false, code: 'INVALID' } }];
return [{ json: { ok: true, teacherId: uid, reqJson: JSON.stringify(q) } }];
